import os
import django
from django.conf import settings
from django.db import models
from django.db import connection

# Configure Django settings
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'test_app',
        ],
    )
    django.setup()

# Define a simple model
class MyModel(models.Model):
    field1 = models.CharField(max_length=100, default="initial1")
    field2 = models.CharField(max_length=100, default="initial2")

    def save(self, *args, **kwargs):
        self.last_update_fields = kwargs.get('update_fields')
        super().save(*args, **kwargs)

    class Meta:
        app_label = 'test_app'

# Create the tables
from django.db.migrations.autocreate_models import AutoCreateModels
AutoCreateModels(connection, [MyModel]).create_models()

def test_update_or_create_update_fields():
    # Create an initial object
    obj = MyModel.objects.create(field1="val1", field2="val2")

    # Update only field1
    defaults = {"field1": "newval1"}
    obj_updated, created = MyModel.objects.update_or_create(field1="val1", defaults=defaults)

    print(f"Created: {created}")
    print(f"Update fields: {obj_updated.last_update_fields}")

    if obj_updated.last_update_fields is None:
        print("FAILURE: update_fields was not passed to save()")
    elif set(obj_updated.last_update_fields) != {"field1"}:
        print(f"FAILURE: update_fields was {obj_updated.last_update_fields}, expected {'field1'}")
    else:
        print("SUCCESS: update_fields was correctly passed")

if __name__ == "__main__":
    test_update_or_create_update_fields()
